#!/usr/bin/env node
/*
 * Bookam mobile app - Sign in with Apple update.
 * Run once from the project root:   node apply-bookam-app-update.js
 *
 * It writes the changed source files, adds the Apple plugin to app.json,
 * and adds the two native dependencies to package.json. After it runs:
 *   1. npx expo install expo-apple-authentication expo-crypto
 *   2. git add -A && git commit && git push
 *   3. rebuild (eas build) - native deps need a fresh build, not Expo Go
 * Safe to run more than once.
 */
const fs = require('fs');
const path = require('path');

const FILES = {
  "lib/appleAuth.ts": "",
  "lib/googleAuth.ts": "",
  "app/auth/login.tsx": "",
  "app/auth/register.tsx": ""
};

for (const [rel, data] of Object.entries(FILES)) {
  const full = path.join(__dirname, rel);
  fs.mkdirSync(path.dirname(full), { recursive: true });
  fs.writeFileSync(full, Buffer.from(data, 'base64'));
  console.log('  wrote  ' + rel);
}

// --- app.json: add the apple plugin + usesAppleSignIn (merge, no clobber) ---
const appJsonPath = path.join(__dirname, 'app.json');
const appJson = JSON.parse(fs.readFileSync(appJsonPath, 'utf8'));
const plugins = appJson.expo.plugins || (appJson.expo.plugins = []);
if (!plugins.includes('expo-apple-authentication')) {
  plugins.push('expo-apple-authentication');
  console.log('  app.json: added expo-apple-authentication plugin');
} else {
  console.log('  app.json: plugin already present');
}
appJson.expo.ios = appJson.expo.ios || {};
if (appJson.expo.ios.usesAppleSignIn !== true) {
  appJson.expo.ios.usesAppleSignIn = true;
  console.log('  app.json: set ios.usesAppleSignIn = true');
}
fs.writeFileSync(appJsonPath, JSON.stringify(appJson, null, 2) + '\n');

// --- package.json: add native deps (merge, keep sorted) ---
const pkgPath = path.join(__dirname, 'package.json');
const pkg = JSON.parse(fs.readFileSync(pkgPath, 'utf8'));
const want = { 'expo-apple-authentication': '~8.0.7', 'expo-crypto': '~15.0.7' };
let changed = false;
for (const [k, v] of Object.entries(want)) {
  if (!pkg.dependencies[k]) { pkg.dependencies[k] = v; changed = true; console.log('  package.json: added ' + k + '@' + v); }
}
if (changed) {
  const sorted = {};
  Object.keys(pkg.dependencies).sort().forEach(k => sorted[k] = pkg.dependencies[k]);
  pkg.dependencies = sorted;
  fs.writeFileSync(pkgPath, JSON.stringify(pkg, null, 2) + '\n');
} else {
  console.log('  package.json: deps already present');
}

console.log('\nDone. Next:');
console.log('  npx expo install expo-apple-authentication expo-crypto');
console.log('  git add -A && git commit -m "add Sign in with Apple" && git push');
console.log('  then rebuild with EAS (Apple sign-in needs a native build, not Expo Go).');
